const items = $input.all();
return items.map(item => {
  let rawValue = item.json.combined_intake_text || '';
  let text = typeof rawValue === 'string' ? rawValue : JSON.stringify(rawValue);
  const tokenMap = {};
  const namePattern = /\b(Mr|Mrs|Ms|Dr|Chief|Alhaji|Alhaja|Barr|Hon|Engr|Justice)\.?\s+[A-Z][a-z]+(?:\s+[A-Z][a-z]+)*/g;
  const matches = [...new Set(Array.from(text.matchAll(namePattern)).map(m => m[0]))];
  matches.forEach((name, i) => { const token = `[PARTY_${i+1}]`; tokenMap[token] = name; text = text.split(name).join(token); });
  return { json: { ...item.json, scrubbed_text: text, token_map: tokenMap } };
});

// Advanced Intake Parser: Routes results to Memory and Orchestrator
const brainOutput = $input.first().json;

// 1. Gather original intake metadata
let intakeData = {};
try {
  intakeData = $("Consolidate Intake package").first().json;
} catch (e) {
  intakeData = $("Consolidate Intake package1").first().json;
}

// 2. Parse AI Analysis
let analysis = {};
try {
  const content = brainOutput.message?.content || '{}';
  analysis = JSON.parse(content.replace(/```json|```/g, '').trim());
} catch(e) {
  analysis = { 
    action: 'intake', 
    summary: 'Detailed extraction failed. Proceeding with raw data.',
    legal_plan: { objective: 'Process existing instructions', orchestrator_agent: 'research_agent' }
  };
}

// 3. Final Package Delivery
return [{
  json: {
    // Priority Header: Dictates WF-02 & WF-03 Routing
    action: analysis.action || 'intake',

    // Legal Intelligence Data
    ...analysis,

    // Metadata & Traceability
    ...intakeData,
    processed_at: new Date().toISOString(),
    brain_model: "gpt-4o-mini"
  }
}];

// Robust Intake Normalizer: Captures Text, Metadata, and Multiple Files
const items = $input.all();
let normalized = [];

items.forEach(item => {
  const data = item.json;
  const sender = data.From || data.message?.from?.id || data.from || data.body?.sender || 'unknown';
  const group_id = `INTAKE-${Date.now()}`;

  const textParts = [
    data.textHtml, data.text, data.Body, data.message?.text, data.body?.content
  ];

  Object.keys(data).forEach(key => {
    if (typeof data[key] === 'string' && !['From', 'from', 'sender', 'timestamp', 'channel'].includes(key)) {
      if (!textParts.includes(data[key])) textParts.push(data[key]);
    }
  });

  const clean_text = textParts.filter(part => typeof part === 'string' && part.trim() !== '').join('\n---\n').trim();
  const channel = data.From ? 'whatsapp' : (data.message ? 'telegram' : (data.from ? 'email' : (clean_text.length > 0 ? 'form' : 'web')));

  const attachments = item.binary ? Object.keys(item.binary) : [];
  attachments.forEach((key, idx) => {
    normalized.push({
      json: {
        sender, channel, timestamp: new Date().toISOString(),
        original_instructions: clean_text, 
        media_type: item.binary[key].fileExtension || 'unknown',
        intake_id: group_id,
        is_deadline: false
      },
      binary: { data: item.binary[key] }
    });
  });

  normalized.push({
    json: {
      sender, channel, timestamp: new Date().toISOString(),
      original_instructions: clean_text,
      media_type: 'payload_sync',
      intake_id: group_id,
      is_deadline: true
    }
  });
});
return normalized;

// Multi-Modal Aggregator: Combines Parallel Results Into One Package
const items = $input.all();

const isDeadlineTrigger = items.some(item => item.json.is_deadline === true);

if (!isDeadlineTrigger) {
  return []; 
}

const finalResults = [];

const extractText = (nodeName, label) => {
  try {
    // Node name MUST MATCH EXACTLY what is in the workflow canvas
    const nodeItems = $(nodeName).all();
    nodeItems.forEach(item => {
      const text = item.json.text || 
                   item.json.message?.content || 
                   item.json.content || 
                   item.json.original_instructions || 
                   '';
      if (text.trim()) {
        finalResults.push(`[${label}]:\n${text.trim()}`);
      }
    });
  } catch (e) {}
};

extractText("Intake Sync Deadline", "LAWYER INSTRUCTIONS");
extractText("Whisper STT", "VOICE TRANSCRIPTION");
extractText("Vision OCR & Analysis", "IMAGE ANALYSIS");
extractText("Local OCR (PDF/Docs)", "DOCUMENT SCAN");

const combined = [...new Set(finalResults)].join('\n\n' + '='.repeat(20) + '\n\n');

return [{
  json: {
    ...items[0].json,
    combined_intake_text: combined || "No text instructions or data found.",
    processed_at: new Date().toISOString()
  }
}];
